_SYSTEM_MESSAGE_KEYS = {
    text: key for key, texts in SYSTEM_MESSAGES.items() for text in texts
}
for key, (turkish, english) in SYSTEM_MESSAGES.items():
    TRANSLATIONS["tr"][key] = turkish
    TRANSLATIONS["en"][key] = english
TRANSLATIONS["es"] = SPANISH_STRINGS
TRANSLATIONS["fr"] = FRENCH_STRINGS
for language, strings in PAGE_STRINGS.items():
    TRANSLATIONS[language].update(strings)
for language, strings in USER_STRINGS.items():
    TRANSLATIONS[language].update(strings)
for language, strings in ADMIN_LAYOUT_STRINGS.items():
    TRANSLATIONS[language].update(strings)
for language, strings in EDITOR_STRINGS.items():
    TRANSLATIONS[language].update(strings)
for language, strings in WORKFLOW_STRINGS.items():
    TRANSLATIONS[language].update(strings)
for language, strings in MAINTENANCE_STRINGS.items():
    TRANSLATIONS[language].update(strings)
for language, strings in REGISTRATION_STRINGS.items():
    TRANSLATIONS[language].update(strings)
for language, strings in TIMEZONE_STRINGS.items():
    TRANSLATIONS[language].update(strings)
for language, strings in ACCOUNT_STRINGS.items():
    TRANSLATIONS[language].update(strings)
_SYSTEM_MESSAGE_KEYS[ACCOUNT_STRINGS["en"]["audit_account_closed"]] = "audit_account_closed"
for language, strings in STORAGE_STRINGS.items():
    TRANSLATIONS[language].update(strings)
_SYSTEM_MESSAGE_KEYS[STORAGE_STRINGS["en"]["quota_exceeded"]] = "quota_exceeded"
_SYSTEM_MESSAGE_KEYS["Default media quotas updated"] = "quota_saved"
_SYSTEM_MESSAGE_KEYS["Personal media quota updated"] = "quota_saved"
for key, message in REGISTRATION_STRINGS["en"].items():
    if key.startswith("audit_"):
        _SYSTEM_MESSAGE_KEYS[message] = key
for key, message in WORKFLOW_STRINGS["en"].items():
    if key.startswith("audit_"):
        _SYSTEM_MESSAGE_KEYS[message] = key
for key in ("staff_session_opened", "staff_login_failed", "staff_login_limited", "staff_auth_rejected"):
    _SYSTEM_MESSAGE_KEYS[TRANSLATIONS["en"][key]] = key


def system_message(request: Request | None, message: str) -> str:
    """Translate only recognized system messages into the current UI language."""
    key = _SYSTEM_MESSAGE_KEYS.get(message)
    if key:
        return translate(request, key)
    for prefix, label_key in (("Dış URL: ", "external_url"), ("İkon URL: ", "image_url")):
        if message.startswith(prefix):
            label = prefix[:-2] if ui_language(request) == "tr" else translate(request, label_key)
            return f"{label}: {system_message(request, message[len(prefix):])}"
    return message
